import{z as A,x as s,o as t,c as p,q as i,j as d,D as o,d as r,s as n,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"无锁栈与 hazard pointer","description":"","frontmatter":{"title":"无锁栈与 hazard pointer","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hazard-pointer.md","filePath":"cs/hazard-pointer.md","lastUpdated":1791413859000}'),B={name:"cs/hazard-pointer.md"};function h(c,a,m,P,C,D){const E=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=i('<h1 id="无锁栈与-hazard-pointer" tabindex="-1">无锁栈与 hazard pointer <a class="header-anchor" href="#无锁栈与-hazard-pointer" aria-label="Permalink to &quot;无锁栈与 hazard pointer&quot;">​</a></h1><div class="epigraph"><p>Treiber 栈用 CAS 换头，ABA 几乎是默认陷阱。Hazard pointer：读者先公布「我正抓着这些指针」，回收者跳过仍被抓的节点。</p><footer>—— 据 Treiber, Systems Programming: Coping with Parallelism, IBM 1986；Michael, Hazard Pointers: Safe Memory Reclamation for Lock-Free Objects, IEEE TPDS 2004 整理</footer></div><p><a href="/cs/michael-scott-queue">上一课</a> 留下节点何时 <code>free</code>。<a href="/cs/lockfree-aba">无锁与 ABA</a> 已给现象。<a href="/cs/rcu-gp">RCU 宽限期</a> 是另一回收。本课不重讲 dummy 节点。缺口是 Treiber 栈 + hazard pointer 回收合同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>栈：<code>head</code> 指向单链。push：新节点 <code>next=head</code>，CAS <code>head</code>。pop：读 <code>h</code>，CAS <code>head</code> 到 <code>h-&gt;next</code>。ABA：pop 读 next 后，<code>h</code> 被弹出再压回，CAS 仍成功但 next 陈旧。hazard：线程进入临界前把指针写入 HP 槽并屏障，扫描时若节点出现在任一 HP 中则延后释放。缺口是<strong>把「还在被读的地址」显式登记</strong>，而不靠停全世界。</p><p><span class="marginnote">直觉类比：HP 像公共冰箱上的便利贴——「这盒酸奶（地址）我还要吃，别扔」。回收者清冰箱前扫一眼所有便利贴，被点名的酸奶留到下一轮。便利贴写错地址或忘了写，你伸手时酸奶就可能已经消失，这正是漏登记等于 UAF 的原因。</span></p><p><span class="marginnote">Treiber 1986 技术报告。Michael, <em>IEEE Trans. Parallel and Dist. Systems</em>, 2004（PODC 2004 前身）。epoch/QSBR 是批量版，RCU 课已见。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每线程少量 HP 槽（栈 pop 常 1–2 个）。退休列表攒一批再扫描 HP。漏登记 = UAF；多登记只延迟回收。与带 tag 的双字 CAS：tag 防 ABA 但不防 UAF，常要两者或再加池。</p><p><span class="marginnote">术语翻译：「退休列表」就是先不还、挂账的手段——节点从栈上摘下后不马上 free，先记进本线程的待释放清单，等确认没有人的 HP 槽还指着它，再分批真正归还。挂账越久内存峰值越高，还早了一步就是 use-after-free。</span></p>',10)),(t(),d(l,null,{default:o(()=>[n(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20POP%5B%22pop%20%E8%AF%BB%20head%22%5D%20--%3E%20HP%5B%22%E5%86%99%E5%85%A5%20hazard%20%E6%A7%BD%22%5D%0A%20%20HP%20--%3E%20CAS%5B%22CAS%20%E6%8D%A2%E5%A4%B4%22%5D%0A%20%20RET%5B%22%E9%80%80%E4%BC%91%E8%8A%82%E7%82%B9%22%5D%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%E5%85%A8%E9%83%A8%20HP%22%5D%0A%20%20SCAN%20--%3E%20FREE%5B%22%E6%9C%AA%E5%91%BD%E4%B8%AD%E5%88%99%E5%8F%AF%E9%87%8A%E6%94%BE%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[r("与 MS 队列：同样需要 HP 或 epoch 保护 "),e("code",null,"head/tail/next"),r("。与 RCU：RCU 读侧更轻、写侧等宽限期；HP 读侧要写槽。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"进度：扫描 HP 是回收者的活，读者无锁。槽要避免伪共享。本课不写攻击性 UAF exploit。并发哈希表下一课把桶锁或无锁探针对上字典，不是栈。",-1)),a[6]||(a[6]=e("p",null,"一个节点从退休到真正释放，中间凭什么能被拦下：",-1)),(t(),d(l,null,{default:o(()=>[n(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20R1%5B%22%E8%AF%BB%E8%80%85%3A%20%E6%8B%BF%E5%88%B0%E8%8A%82%E7%82%B9%20X%22%5D%20--%3E%20R2%5B%22%E6%8A%8A%20X%20%E5%86%99%E8%BF%9B%20HP%20%E6%A7%BD%22%5D%0A%20%20R2%20--%3E%20R3%7B%22CAS%20%E5%89%8D%20X%20%E8%A2%AB%E5%BC%B9%E5%87%BA%3F%22%7D%0A%20%20R3%20--%20%22%E6%98%AF%22%20--%3E%20RET%5B%22X%20%E8%BF%9B%E9%80%80%E4%BC%91%E5%88%97%E8%A1%A8%22%5D%0A%20%20RET%20--%3E%20SCAN%7B%22%E6%89%AB%E6%8F%8F%3A%20X%20%E5%87%BA%E7%8E%B0%E5%9C%A8%E4%BB%BB%E4%B8%80%20HP%20%E6%A7%BD%3F%22%7D%0A%20%20SCAN%20--%20%22%E5%91%BD%E4%B8%AD%22%20--%3E%20WAIT%5B%22%E5%BB%B6%E5%90%8E%E9%87%8A%E6%94%BE%2C%20%E7%95%99%E5%9C%A8%E5%88%97%E8%A1%A8%22%5D%0A%20%20SCAN%20--%20%22%E6%9C%AA%E5%91%BD%E4%B8%AD%22%20--%3E%20FREE%5B%22%E7%9C%9F%E6%AD%A3%20free%20X%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p><span class="marginnote">为什么重要：HP 槽若紧紧排在一起，各核写「自己的」槽也会落进同一缓存行，槽与槽互相把对方的行打回内存——这就是伪共享。把每线程的槽补齐到缓存行大小，扫描才不会把读侧的无锁优势悄悄磨掉。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 SMR（EBR、HE、PEBR）列成百科。实时最坏扫描 HP 与线程数有关。有序/无序字典的并发下一课。</p><p>后课默认：无锁链表回收用 HP 或 epoch。并发映射用分段锁或无锁桶。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Treiber 栈：CAS 头；ABA 与回收绑定。</li><li>Hazard pointer：公布指针，退休时扫描。</li><li>下一课并发哈希表。</li><li>出处：Treiber, 1986；Michael, <em>TPDS</em>, 2004。</li></ul>',6))])}const S=A(B,[["render",h]]);export{u as __pageData,S as default};
